from pathlib import Path
s=Path('browser-collision22-round-2.js').read_text(encoding='utf-8')
s=s.replace("await page.locator('#rounds').click();", "await page.setViewportSize({width:1440,height:900});await page.goto('http://127.0.0.1:3000/?ground=32');await page.locator('#rounds').click();")
s=s.replace("await move(0,335);await jump(550);", """await move(0,335);let pose=JSON.parse(await page.locator('#game').getAttribute('data-plunger'));if(pose.stage!=='compressed')throw Error('Plunger did not compress');await page.screenshot({path:'output/playwright/ground32-compressed.png'});await select(0);await page.keyboard.press('Space');await wait(25);pose=JSON.parse(await page.locator('#game').getAttribute('data-plunger'));if(pose.stage!=='release')throw Error('No plunger release '+JSON.stringify(pose));await page.screenshot({path:'output/playwright/ground32-release.png'});await move(0,550);await wait(1000);""")
s=s[:s.rfind('}')]+"return {cleared:(await state()).won,health:(await state()).heroes.map(h=>h.hp)};\n}"
Path('browser-ground32-bankshot.js').write_text(s,encoding='utf-8')
# Survey floors and camera views via ordinary controls and level menu.
Path('browser-ground32-survey.js').write_text('''async page=>{await page.setViewportSize({width:1440,height:900});await page.goto('http://127.0.0.1:3000/?ground=32');const results=[];const check=async round=>{const d=await page.locator('#game').evaluate(el=>({camera:JSON.parse(el.dataset.camera),layers:JSON.parse(el.dataset.parallax),round:Number(el.dataset.round)}));if(d.round!==round)throw Error('Wrong round');for(const layer of d.layers.slice(1)){if(Math.abs(layer.bottom+d.camera.y-610)>1)throw Error('Detached scenery '+JSON.stringify(d));}results.push({round,cameraY:d.camera.y,bases:d.layers.slice(1).map(l=>l.bottom+d.camera.y)});};for(let round=0;round<6;round++){await page.locator('#rounds').click();await page.locator('button[data-round="'+round+'"]').click();await page.waitForTimeout(300);await check(round);await page.screenshot({path:'output/playwright/ground32-level-'+round+'.png'});await page.locator('#zoom').click();await page.waitForTimeout(150);await check(round);await page.locator('#zoom').click();}await page.locator('#rounds').click();await page.locator('button[data-round="2"]').click();await page.waitForTimeout(300);await page.keyboard.down('ArrowRight');await page.waitForTimeout(1100);await page.keyboard.up('ArrowRight');await page.waitForTimeout(250);await page.keyboard.press('Space');await page.waitForTimeout(550);await check(2);await page.setViewportSize({width:390,height:844});await page.waitForTimeout(500);await check(2);return results;}''',encoding='utf-8')
